const menu=document.querySelector('.menu');const nav=document.querySelector('.nav');menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});nav?.addEventListener('click',e=>{if(e.target.matches('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
document.querySelectorAll('.billing button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.billing button').forEach(b=>b.classList.remove('active'));button.classList.add('active');const period=button.dataset.period;document.querySelectorAll('[data-monthly]').forEach(price=>{price.textContent=price.dataset[period]})}));
